1	'use client'
2	
3	import { useState, useCallback, useEffect, useMemo } from 'react'
4	import { useSearchParams, useRouter } from 'next/navigation'
5	import { Users, SearchX, BookmarkX, Plus, Loader2 } from 'lucide-react'
6	import { toast } from 'sonner'
7	import { Button } from '@/components/ui/button'
8	import { ClientsTable } from '@/components/clients/ClientsTable'
9	import { ClientFilterBar, type ClientFilters } from '@/components/clients/ClientFilterBar'
10	import { BulkActionsBar } from '@/components/clients/BulkActionsBar'
11	import { SavedViewSwitcher, type ClientView } from '@/components/clients/SavedViewSwitcher'
12	import { SavedViewManager } from '@/components/clients/SavedViewManager'
13	import { ClientDrawer } from '@/components/clients/ClientDrawer'
14	import dynamic from 'next/dynamic'
15	import { Skeleton } from '@/components/ui/skeleton'
16	
17	// B3 fix: code-split Tiptap out of the /clients route initial bundle (~130KB)
18	const AddNoteModal = dynamic(
19	  () => import('@/components/clients/notes/AddNoteModal').then((m) => ({ default: m.AddNoteModal })),
20	  { ssr: false, loading: () => <Skeleton className="h-10 w-full rounded-lg" /> },
21	)
22	import { DataState } from '@/components/shared/DataState'
23	import { EmptyState } from '@/components/shared/EmptyState'
24	import { PageError } from '@/components/shared/PageError'
25	import { PullToRefresh } from '@/components/shared/PullToRefresh'
26	import { TableSkeleton } from '@/components/skeletons'
27	import { Alert, AlertDescription } from '@/components/ui/alert'
28	import type { ClientTag } from '@/components/clients/TagChip'
29	import type { Database } from '@/lib/supabase/types'
30	
31	type Client = Database['public']['Tables']['clients']['Row']
32	
33	interface ClientsPageClientProps {
34	  initialClients: Client[]
35	  tagLibrary: ClientTag[]
36	}
37	
38	const DEFAULT_FILTERS: ClientFilters = {
39	  q: '',
40	  tags: [],
41	  vip: false,
42	  inactive: false,
43	  noShows: false,
44	  showArchived: false,
45	  hasAlerts: false,
46	  spendingTier: '',
47	  artistIds: [],
48	  serviceIds: [],
49	  lastVisitRange: '',
50	}
51	
52	export function ClientsPageClient({ initialClients, tagLibrary }: ClientsPageClientProps) {
53	  const router = useRouter()
54	  const searchParams = useSearchParams()
55	
56	  const [clients, setClients] = useState<Client[]>(initialClients)
57	  const [filters, setFilters] = useState<ClientFilters>(DEFAULT_FILTERS)
58	  const [selectedIds, setSelectedIds] = useState<string[]>([])
59	  const [loading, setLoading] = useState(false)
60	  const [fetchError, setFetchError] = useState<Error | null>(null)
61	  const [drawerOpen, setDrawerOpen] = useState(false)
62	  const [editingClient, setEditingClient] = useState<Client | null>(null)
63	  const [noteClientId, setNoteClientId] = useState<string | null>(null)
64	  const [page, setPage] = useState(1)
65	  const [hasMore, setHasMore] = useState(false)
66	  const [totalCount, setTotalCount] = useState<number | null>(null)
67	
68	  // Saved views
69	  const [views, setViews] = useState<ClientView[]>([])
70	  const [activeViewId, setActiveViewId] = useState<string | null>(null)
71	  const [viewManagerOpen, setViewManagerOpen] = useState(false)
72	  const [viewManagerMode, setViewManagerMode] = useState<'create' | 'edit'>('create')
73	  const [editingView, setEditingView] = useState<ClientView | null>(null)
74	  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false)
75	
76	  const fetchViews = useCallback(async () => {
77	    try {
78	      const res = await fetch('/api/client-views')
79	      if (res.ok) {
80	        const json = await res.json() as { data: ClientView[] }
81	        setViews(json.data ?? [])
82	        // Auto-activate first system default view
83	        const defaultView = json.data?.find((v) => v.is_default)
84	        if (defaultView) {
85	          setActiveViewId((prev) => prev ?? defaultView.id)
86	        }
87	      }
88	    } catch {
89	      toast.error('Failed to load views', { description: 'Using All clients as default' })
90	    }
91	  }, [])
92	
93	  // Load saved views on mount
94	  useEffect(() => {
95	    void fetchViews()
96	  }, [fetchViews])
97	
98	  // Restore page from URL
99	  useEffect(() => {
100	    const p = parseInt(searchParams.get('page') ?? '1', 10)
101	    if (p > 1) {
102	      setPage(p)
103	    }
104	  }, []) // eslint-disable-line react-hooks/exhaustive-deps
105	
106	  const fetchClients = useCallback(async (f: ClientFilters, p = 1) => {
107	    setLoading(true)
108	    setFetchError(null)
109	    try {
110	      const params = new URLSearchParams()
111	      if (f.q) params.set('q', f.q)
112	      if (f.tags.length) params.set('tags', f.tags.join(','))
113	      if (f.vip) params.set('vip', 'true')
114	      if (f.inactive) params.set('inactive', 'true')
115	      if (f.noShows) params.set('no_show', 'true')
116	      if (!f.showArchived) params.set('archived', 'false')
117	      else params.set('archived', 'any')
118	      if (f.spendingTier) params.set('spending', f.spendingTier)
119	      if (f.artistIds.length) params.set('artist_ids', f.artistIds.join(','))
120	      if (f.serviceIds.length) params.set('service_ids', f.serviceIds.join(','))
121	      if (f.lastVisitRange) params.set('last_visit_range', f.lastVisitRange)
122	      params.set('page', String(p))
123	      params.set('per_page', '50')
124	
125	      const res = await fetch(`/api/clients?${params.toString()}`)
126	      if (!res.ok) throw new Error('Failed to load clients')
127	      const json = await res.json() as { data: Client[]; count: number }
128	
129	      if (p === 1) {
130	        setClients(json.data ?? [])
131	      } else {
132	        setClients((prev) => [...prev, ...(json.data ?? [])])
133	      }
134	      setTotalCount(json.count ?? null)
135	      setHasMore((json.data?.length ?? 0) >= 50)
136	    } catch (err) {
137	      setFetchError(err instanceof Error ? err : new Error('Failed to load clients'))
138	    } finally {
139	      setLoading(false)
140	    }
141	  }, [])
142	
143	  useEffect(() => {
144	    void fetchClients(filters, 1)
145	    setPage(1)
146	    setSelectedIds([])
147	  }, [filters, fetchClients])
148	
149	  function handleFiltersChange(f: ClientFilters) {
150	    setFilters(f)
151	    setHasUnsavedChanges(true)
152	  }
153	
154	  function handleViewChange(viewId: string | null) {
155	    setActiveViewId(viewId)
156	    setHasUnsavedChanges(false)
157	    const view = views.find((v) => v.id === viewId)
158	    if (view) {
159	      // Apply view filters
160	      const viewFilters = view.filters as Partial<ClientFilters>
161	      setFilters({ ...DEFAULT_FILTERS, ...viewFilters })
162	    } else {
163	      setFilters(DEFAULT_FILTERS)
164	    }
165	  }
166	
167	  async function handleDeleteView(viewId: string) {
168	    try {
169	      const res = await fetch(`/api/client-views/${viewId}`, { method: 'DELETE' })
170	      if (!res.ok) throw new Error('Failed to delete view')
171	      setViews((prev) => prev.filter((v) => v.id !== viewId))
172	      if (activeViewId === viewId) {
173	        const defaultView = views.find((v) => v.is_default)
174	        setActiveViewId(defaultView?.id ?? null)
175	      }
176	      toast.success('View deleted')
177	    } catch {
178	      toast.error('Failed to delete view')
179	    }
180	  }
181	
182	  async function handleDuplicateView(view: ClientView) {
183	    try {
184	      const res = await fetch('/api/client-views', {
185	        method: 'POST',
186	        headers: { 'Content-Type': 'application/json' },
187	        body: JSON.stringify({
188	          name: `${view.name} (copy)`,
189	          filters: view.filters,
190	          scope: 'private',
191	        }),
192	      })
193	      if (!res.ok) throw new Error('Failed to duplicate view')
194	      const json = await res.json() as { data: ClientView }
195	      setViews((prev) => [...prev, json.data])
196	      toast.success('View duplicated')
197	    } catch {
198	      toast.error('Failed to duplicate view')
199	    }
200	  }
201	
202	  async function handleSetDefaultView(view: ClientView) {
203	    try {
204	      const res = await fetch(`/api/client-views/${view.id}`, {
205	        method: 'PATCH',
206	        headers: { 'Content-Type': 'application/json' },
207	        body: JSON.stringify({ is_default: true }),
208	      })
209	      if (!res.ok) throw new Error('Failed to set default')
210	      // Optimistically update local state so the star + dropdown sync instantly.
211	      setViews((prev) => prev.map((v) => ({ ...v, is_default: v.id === view.id })))
212	      toast.success(`"${view.name}" is now your default view`)
213	    } catch {
214	      toast.error('Failed to set default view')
215	    }
216	  }
217	
218	  function handleViewSaved(savedView: ClientView) {
219	    setViews((prev) => {
220	      const idx = prev.findIndex((v) => v.id === savedView.id)
221	      if (idx >= 0) {
222	        const next = [...prev]
223	        next[idx] = savedView
224	        return next
225	      }
226	      return [...prev, savedView]
227	    })
228	    setActiveViewId(savedView.id)
229	    setHasUnsavedChanges(false)
230	  }
231	
232	  function handleLoadMore() {
233	    const nextPage = page + 1
234	    setPage(nextPage)
235	    router.replace(`?page=${nextPage}`, { scroll: false })
236	    void fetchClients(filters, nextPage)
237	  }
238	
239	  function handleEditClient(client: Client) {
240	    setEditingClient(client)
241	    setDrawerOpen(true)
242	  }
243	
244	  function handleNewClient() {
245	    setEditingClient(null)
246	    setDrawerOpen(true)
247	  }
248	
249	  function handleDrawerSuccess(client: Client) {
250	    setClients((prev) => {
251	      const idx = prev.findIndex((c) => c.id === client.id)
252	      if (idx >= 0) {
253	        const next = [...prev]
254	        next[idx] = client
255	        return next
256	      }
257	      return [client, ...prev]
258	    })
259	  }
260	
261	  const hasActiveFilters = !!(
262	    filters.q || filters.tags.length > 0 || filters.vip ||
263	    filters.inactive || filters.noShows || filters.spendingTier ||
264	    filters.artistIds.length > 0 || filters.serviceIds.length > 0 || filters.lastVisitRange
265	  )
266	
267	  const inactiveCount = useMemo(() => {
268	    const cutoff = Date.now() - 90 * 24 * 60 * 60 * 1000
269	    return clients.filter(
270	      (c) => !c.archived_at && c.last_visit_at !== null && new Date(c.last_visit_at).getTime() < cutoff
271	    ).length
272	  }, [clients])
273	
274	  const activeView = views.find((v) => v.id === activeViewId) ?? null
275	  const isInitialLoad = loading && clients.length === 0
276	
277	  return (
278	    <PullToRefresh
279	      onRefresh={async () => { router.refresh() }}
280	      className="flex flex-col gap-4"
281	    >
282	      {/* Toolbar row — saved views on the left, count + primary action on the right.
283	          The page-level heading + description are rendered by the server page's PageHeader. */}
284	      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
285	        {views.length > 0 ? (
286	          <SavedViewSwitcher
287	            views={views}
288	            activeViewId={activeViewId}
289	            onViewChange={handleViewChange}
290	            onCreateView={() => {
291	              setViewManagerMode('create')
292	              setEditingView(null)
293	              setViewManagerOpen(true)
294	            }}
295	            onEditView={(view) => {
296	              setViewManagerMode('edit')
297	              setEditingView(view)
298	              setViewManagerOpen(true)
299	            }}
300	            onDuplicateView={handleDuplicateView}
301	            onDeleteView={handleDeleteView}
302	            onSetDefault={handleSetDefaultView}
303	          />
304	        ) : (
305	          <div />
306	        )}
307	
308	        <div className="flex items-center gap-2">
309	          {totalCount !== null && (
310	            <span className="text-xs text-muted-foreground tabular-nums whitespace-nowrap">
311	              {clients.length} of {totalCount} client{totalCount !== 1 ? 's' : ''}
312	            </span>
313	          )}
314	          {inactiveCount > 0 && (
315	            <span
316	              title={`${inactiveCount} client${inactiveCount !== 1 ? 's' : ''} not seen in 90+ days`}
317	              className="inline-flex items-center gap-1 rounded-full bg-destructive/10 text-destructive text-[11px] font-medium px-2 py-0.5 select-none"
318	            >
319	              <span className="h-1.5 w-1.5 rounded-full bg-destructive shrink-0" aria-hidden="true" />
320	              {inactiveCount} inactive
321	            </span>
322	          )}
323	          <Button size="sm" onClick={handleNewClient}>
324	            <Plus className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
325	            New client
326	          </Button>
327	        </div>
328	      </div>
329	
330	      {/* Unsaved changes banner */}
331	      {hasUnsavedChanges && activeView && !activeView.is_system && (
332	        <Alert className="py-2 border-warning/30 bg-warning/5">
333	          <AlertDescription className="flex items-center justify-between gap-3 text-xs">
334	            <span className="text-warning dark:text-warning-foreground">
335	              Unsaved changes. Save view or discard?
336	            </span>
337	            <div className="flex gap-2 shrink-0">
338	              <Button
339	                size="sm"
340	                variant="outline"
341	                className="h-6 text-xs px-2"
342	                onClick={() => {
343	                  setFilters({ ...DEFAULT_FILTERS, ...(activeView.filters as Partial<ClientFilters>) })
344	                  setHasUnsavedChanges(false)
345	                }}
346	              >
347	                Discard
348	              </Button>
349	              <Button
350	                size="sm"
351	                className="h-6 text-xs px-2"
352	                onClick={() => {
353	                  setViewManagerMode('edit')
354	                  setEditingView(activeView)
355	                  setViewManagerOpen(true)
356	                }}
357	              >
358	                Save view
359	              </Button>
360	            </div>
361	          </AlertDescription>
362	        </Alert>
363	      )}
364	
365	      <ClientFilterBar
366	        filters={filters}
367	        onChange={handleFiltersChange}
368	        tagLibrary={tagLibrary}
369	      />
370	
371	      {selectedIds.length > 0 && (
372	        <BulkActionsBar
373	          selectedIds={selectedIds}
374	          tagLibrary={tagLibrary}
375	          onClearSelection={() => setSelectedIds([])}
376	          onArchived={() => void fetchClients(filters, 1)}
377	          onTagsApplied={() => void fetchClients(filters, 1)}
378	        />
379	      )}
380	
381	      <DataState
382	        data={clients}
383	        isLoading={isInitialLoad}
384	        isError={!!fetchError && clients.length === 0}
385	        error={fetchError}
386	        loadingSlot={<TableSkeleton rows={8} />}
387	        emptySlot={
388	          // Two distinct empty states per Clients Audit v1:
389	          //  1. DB empty (no clients ever created) — onboarding: + New client + CSV hint.
390	          //  2. Filters or saved view returned zero — help user reset.
391	          hasActiveFilters || (activeView && activeViewId) ? (
392	            activeView && activeViewId ? (
393	              <EmptyState
394	                icon={BookmarkX}
395	                title="No clients match these filters"
396	                description={`The filters in "${activeView.name}" returned no results.`}
397	                cta={{
398	                  label: 'Clear filters',
399	                  onClick: () => {
400	                    setFilters(DEFAULT_FILTERS)
401	                    setHasUnsavedChanges(false)
402	                  },
403	                }}
404	                ctaSecondary={{
405	                  label: 'Edit view filters',
406	                  onClick: () => {
407	                    setViewManagerMode('edit')
408	                    setEditingView(activeView)
409	                    setViewManagerOpen(true)
410	                  },
411	                }}
412	                variant="no-results"
413	              />
414	            ) : (
415	              <EmptyState
416	                icon={SearchX}
417	                title="No clients match these filters"
418	                description="Try different filters or clear all to see everyone."
419	                cta={{
420	                  label: 'Clear filters',
421	                  onClick: () => {
422	                    setFilters(DEFAULT_FILTERS)
423	                    setHasUnsavedChanges(false)
424	                  },
425	                }}
426	                variant="no-results"
427	              />
428	            )
429	          ) : (
430	            <EmptyState
431	              icon={Users}
432	              title="Add your first client"
433	              description="Start with a manual entry — CSV import is coming soon."
434	              cta={{ label: '+ New client', onClick: handleNewClient }}
435	              ctaSecondary={{
436	                label: 'Import from CSV',
437	                onClick: () => toast.info('CSV import is coming soon. Add clients manually for now.'),
438	              }}
439	              variant="first-time"
440	            />
441	          )
442	        }
443	        errorSlot={
444	          <PageError
445	            error={fetchError ?? new Error('Failed to load clients')}
446	            reset={() => void fetchClients(filters, 1)}
447	            variant="inline"
448	          />
449	        }
450	      >
451	        {(data) => (
452	          <ClientsTable
453	            clients={data}
454	            tagLibrary={tagLibrary}
455	            loading={loading && data.length === 0}
456	            selectedIds={selectedIds}
457	            onSelectionChange={setSelectedIds}
458	            onEdit={handleEditClient}
459	            onAddNote={(id) => setNoteClientId(id)}
460	          />
461	        )}
462	      </DataState>
463	
464	      {/* Load more */}
465	      {(hasMore || loading) && clients.length > 0 && (
466	        <div className="flex items-center justify-between py-4">
467	          <span className="text-sm text-muted-foreground tabular-nums">
468	            Showing {clients.length}{totalCount !== null ? ` of ${totalCount}` : ''} clients
469	          </span>
470	          {hasMore && (
471	            <Button variant="outline" size="sm" onClick={handleLoadMore} disabled={loading}>
472	              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden="true" />}
473	              Load more
474	            </Button>
475	          )}
476	        </div>
477	      )}
478	
479	      <ClientDrawer
480	        open={drawerOpen}
481	        onOpenChange={(v) => {
482	          setDrawerOpen(v)
483	          if (!v) setEditingClient(null)
484	        }}
485	        client={editingClient}
486	        tagLibrary={tagLibrary}
487	        onSuccess={handleDrawerSuccess}
488	      />
489	
490	      {noteClientId && (
491	        <AddNoteModal
492	          open={Boolean(noteClientId)}
493	          onOpenChange={(v) => { if (!v) setNoteClientId(null) }}
494	          clientId={noteClientId}
495	        />
496	      )}
497	
498	      <SavedViewManager
499	        open={viewManagerOpen}
500	        onOpenChange={setViewManagerOpen}
501	        mode={viewManagerMode}
502	        view={editingView}
503	        currentFilters={filters}
504	        onSaved={handleViewSaved}
505	      />
506	    </PullToRefresh>
507	  )
508	}
